// components/Navbar.js
import React from 'react';
import { useAuth } from '../context/AuthContext';

const Navbar = () => {
  const { user, cart } = useAuth();

  // ✅ Простая функция для перехода на вкладку профиля
  const goToProfileTab = (tab) => {
    window.location.hash = tab; // Просто устанавливаем hash как название таба
  };

  // ✅ Функция для перехода в каталог
  const goToCatalog = () => {
    window.location.hash = 'catalog';
  };

  // Виджет корзины
  const CartWidget = () => (
    <div 
      className="relative cursor-pointer"
      onClick={() => goToProfileTab('cart')}
    >
      <span>🛒</span>
      {cart.length > 0 && (
        <span className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full w-5 h-5 text-xs flex items-center justify-center">
          {cart.length}
        </span>
      )}
    </div>
  );

  // Виджет избранного
  const FavoritesWidget = () => (
    <div 
      className="cursor-pointer"
      onClick={() => goToProfileTab('favorites')}
    >
      ❤️
    </div>
  );

  return (
    <nav className="flex justify-between items-center p-4 bg-white shadow-md">
      {/* Логотип */}
      <div 
        className="cursor-pointer text-xl font-bold"
        onClick={goToCatalog}
      >
        Магазин
      </div>

      {user ? (
        <div className="flex items-center space-x-4">
          <FavoritesWidget />
          <CartWidget />
          <div 
            className="cursor-pointer"
            onClick={() => goToProfileTab('profile')}
          >
            👤 Профиль
          </div>
        </div>
      ) : (
        <button 
          onClick={goToCatalog}
          className="bg-gold-600 text-white px-4 py-2 rounded hover:bg-gold-700"
        >
          Войти
        </button>
      )}
    </nav>
  );
};

export default Navbar;
